import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·18","description":"易小帖 - 卷二·18","frontmatter":{"title":"卷二·18","description":"易小帖 - 卷二·18"},"headers":[],"relativePath":"zh/classics/yixiaotie/058.md","filePath":"zh/classics/yixiaotie/058.md"}'),o={name:"zh/classics/yixiaotie/058.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·18",tabindex:"-1"},[r("卷二·18 "),e("a",{class:"header-anchor",href:"#卷二·18","aria-label":"Permalink to “卷二·18”"},"​")],-1),e("p",null,"「震來虩虩」，虩字不見他書，即音與義亦不明。嘗考許叔重《說文》，虩字無訓，但引易雲「履虎尾虩虩恐懼」。按履卦四爻祗有「履虎尾愬愬終吉」，並無「虩虩恐懼」四字，疑有錯誤。後觀黃氏《韻會》，其釋愬字曰：音與索同。又雲：驚懼謂之愬。而丁氏《集韻》則雲：或作虩，亦作覤。至毛晃《增韻》則並出愬虩覤三字，皆釋驚恐，始知《說文》所引虩虩即愬愬，其引易文則止「履虎尾虩虩」五字，而恐懼二字則釋虩虩之文也。履卦止愬愬，而震卦有虩虩、蘇蘇、索索三重字，虩與索與愬同音，皆生責切。而愬與蘇又同音，皆生徂切。惟毛晃音汔逆切稍異，而其釋恐懼則諸書並同。宋儒不識蘇蘇索索之解，誤祖虞仲翔說，謂蘇者死而復生，索者索然氣盡，吳澄熊過奉為金科，至妄為解義雲：虩者蠅虎之名，則豈有生物名而疊之作重字者。其誕妄可知也。（按覤亦重字，莊子覤覤然驚。）",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
